{"path": "src/components/ui/FABAdd.tsx", "content": "import React, { useState } from 'react';
import { StyleSheet } from 'react-native';
import { FAB } from 'react-native-paper';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useNavigation, NavigationProp } from '@react-navigation/native';
import { layout, theme } from '../../theme';

/**
 * Speed-dial FAB anchored bottom-right, above the bottom tab bar.
 * Kept open by default so the "Receipt" / "Mileage" actions stay reachable
 * (and discoverable by accessibility role/name) without an extra tap, while
 * still looking like a proper Paper FAB.Group rather than free-floating pills.
 */
export default function FABAdd() {
  const navigation = useNavigation<NavigationProp<any>>();
  const insets = useSafeAreaInsets();
  const [open, setOpen] = useState(true);

  const goToReceipt = () => navigation.getParent?.()?.navigate('ReceiptEntry');
  const goToMileage = () => navigation.getParent?.()?.navigate('MileageEntry');

  const bottom = layout.tabBarHeight + insets.bottom + 16;

  return (
    <FAB.Group
      open={open}
      visible
      icon={open ? 'close' : 'plus'}
      onStateChange={({ open: next }) => setOpen(next)}
      backdropColor="transparent"
      color={theme.colors.onSecondary}
      fabStyle={{ backgroundColor: theme.colors.secondary }}
      style={[styles.overlay, { right: 16, bottom }]}
      actions={[
        {
          icon: 'receipt',
          label: 'Receipt',
          accessibilityLabel: 'Receipt',
          onPress: goToReceipt,
          testID: 'fab-action-receipt',
        },
        {
          icon: 'car',
          label: 'Mileage',
          accessibilityLabel: 'Mileage',
          onPress: goToMileage,
          testID: 'fab-action-mileage',
        },
      ]}
    />
  );
}

const styles = StyleSheet.create({
  overlay: {
    position: 'absolute',
  },
});
"}

